/**
 * VAPID keys for Web Push alerts (RFC 8292). One P-256 key pair per installation: the public key
 * is what browsers subscribe with, the private key signs every push request. Generated by the
 * installer, by `skiff-update-self` on hosts installed before push existed, and by the root
 * `skiff-platform-config` helper when the dashboard asks (`push-keys`). Never rotated
 * automatically: a new key pair silently invalidates every existing browser subscription.
 *
 * Pure `node:crypto`, so the installer, the updater (a compiled binary) and the helper share it.
 */
import { createECDH, generateKeyPairSync } from 'node:crypto';

export const VAPID_PUBLIC_KEY_ENV = 'SKIFF_VAPID_PUBLIC_KEY';
export const VAPID_PRIVATE_KEY_ENV = 'SKIFF_VAPID_PRIVATE_KEY';
/** Optional `mailto:` or `https:` contact; defaults to the platform origin (or a mailto on http). */
export const VAPID_SUBJECT_ENV = 'SKIFF_VAPID_SUBJECT';

export interface VapidKeys {
	/** Uncompressed P-256 point (65 bytes), base64url: the browser's `applicationServerKey`. */
	publicKey: string;
	/** The 32-byte private scalar, base64url. */
	privateKey: string;
}

export function generateVapidKeys(): VapidKeys {
	const { privateKey } = generateKeyPairSync('ec', { namedCurve: 'prime256v1' });
	const jwk = privateKey.export({ format: 'jwk' });
	const x = Buffer.from(jwk.x!, 'base64url');
	const y = Buffer.from(jwk.y!, 'base64url');
	return {
		publicKey: Buffer.concat([Buffer.from([0x04]), x, y]).toString('base64url'),
		privateKey: Buffer.from(jwk.d!, 'base64url').toString('base64url'),
	};
}

/** Both keys are well formed and belong together. */
export function validVapidKeys(publicKey: string | undefined, privateKey: string | undefined): boolean {
	if (!publicKey || !privateKey) return false;
	if (!/^[A-Za-z0-9_-]+$/.test(publicKey) || !/^[A-Za-z0-9_-]+$/.test(privateKey)) return false;
	const pub = Buffer.from(publicKey, 'base64url');
	const priv = Buffer.from(privateKey, 'base64url');
	if (pub.length !== 65 || pub[0] !== 0x04 || priv.length !== 32) return false;
	try {
		const ecdh = createECDH('prime256v1');
		ecdh.setPrivateKey(priv);
		return ecdh.getPublicKey().equals(pub);
	} catch {
		return false;
	}
}

/**
 * Make sure an env map (skiff.env) holds a valid key pair. Leaves a valid pair alone and replaces
 * a missing, partial or broken one. Returns true when it changed the map.
 */
export function ensureVapidKeys(env: Map<string, string>): boolean {
	if (validVapidKeys(env.get(VAPID_PUBLIC_KEY_ENV), env.get(VAPID_PRIVATE_KEY_ENV))) return false;
	const keys = generateVapidKeys();
	env.set(VAPID_PUBLIC_KEY_ENV, keys.publicKey);
	env.set(VAPID_PRIVATE_KEY_ENV, keys.privateKey);
	return true;
}

/** The `sub` claim: the configured contact, else the https platform origin, else a mailto. */
export function vapidSubject(env: Record<string, string | undefined>): string {
	const configured = env[VAPID_SUBJECT_ENV]?.trim();
	if (configured && /^(mailto:|https:\/\/)/.test(configured)) return configured;
	const origin = env.SKIFF_PLATFORM_ORIGIN?.replace(/\/+$/, '');
	if (origin?.startsWith('https://')) return origin;
	const host = env.SKIFF_CONTENT_DOMAIN || (origin ? new URL(origin).hostname : 'localhost');
	return `mailto:skiff@${host}`;
}
